/**
 * @distilled.cloud/technitium -- Technitium DNS Server SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the structure of
 * Technitium's API documentation and request handlers, mirrored in
 * `specs/spec-mirror-technitium`. Everything else in this folder is
 * hand-written.
 *
 * One module per API area (`zones`, `settings`, `admin`, ...). Operation names
 * come from the documentation's section headings.
 *
 * @example
 * ```ts
 * import * as Technitium from "@distilled.cloud/technitium";
 *
 * const { records } = yield* Technitium.zones.getRecords({ zone: "example.com", domain: "example.com" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  TechnitiumProtocol,
  type TechnitiumOpContext,
  type TechnitiumOpError,
} from "./protocol.ts";
export * from "./services/index.ts";
